namespace { constexpr guint N=5,LIMIT=10; volatile std::sig_atomic_t stop=0; struct Counter {const char* name=nullptr; guint64 buffers=0;}; struct App {std::vector<std::string> labels; guint logged[N]={}; GstPad* pads[N]={}; Counter mux,infer,tracker,tiler,display;}; struct Src {guint id; GstElement *ts=nullptr,*parser=nullptr; bool ts_linked=false,h264_linked=false; guint64 buffers=0;}; void sig(int){stop=1;}
std::vector<std::string> labels(const char*p){std::ifstream f(p);std::vector<std::string>v;std::string s;while(std::getline(f,s))v.push_back(s);return v;} const char* label(NvDsObjectMeta*o,const std::vector<std::string>&v){return o->obj_label[0]?o->obj_label:(o->class_id>=0&&(size_t)o->class_id<v.size()?v[o->class_id].c_str():"unknown");}
std::string redact(const gchar*x,char**v){std::string r=x?x:"";for(int i=1;i<=5;i++){std::string s=v[i];std::string::size_type p=0;while(!s.empty()&&(p=r.find(s,p))!=std::string::npos){r.replace(p,s.size(),"<redacted-hls-url>");p+=18;}}return r;}
GstCaps* caps(GstPad*p){GstCaps*c=gst_pad_get_current_caps(p);return c?c:gst_pad_query_caps(p,nullptr);} bool match(GstCaps*c,const char*s){GstCaps*x=gst_caps_from_string(s);bool ok=c&&x&&gst_caps_can_intersect(c,x);if(x)gst_caps_unref(x);return ok;} void fail(GstElement*e,const char*s){GError*x=g_error_new_literal(GST_STREAM_ERROR,GST_STREAM_ERROR_FAILED,s);gst_element_post_message(e,gst_message_new_error(GST_OBJECT(e),x,nullptr));g_error_free(x);}
GstPadProbeReturn decode(GstPad*p,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;Src*s=(Src*)d;++s->buffers;return GST_PAD_PROBE_OK;} GstPadProbeReturn count(GstPad*,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;Counter*c=(Counter*)d;++c->buffers;return GST_PAD_PROBE_OK;} void hls(GstElement*e,GstPad*p,gpointer d){Src*s=(Src*)d;GstCaps*c=caps(p);if(!match(c,"video/mpegts")){if(c)gst_caps_unref(c);fail(e,"Unsupported HLS output; expected video/mpegts");return;}if(c)gst_caps_unref(c);if(s->ts_linked)return;GstPad*q=gst_element_get_static_pad(s->ts,"sink");if(!q||gst_pad_link(p,q)!=GST_PAD_LINK_OK)fail(e,"Could not link HLS MPEG-TS");else{ s->ts_linked=true;std::cout<<"Source "<<s->id<<": HLS MPEG-TS linked.\n";}if(q)gst_object_unref(q);}
void ts(GstElement*e,GstPad*p,gpointer d){Src*s=(Src*)d;GstCaps*c=caps(p);const GstStructure*z=c?gst_caps_get_structure(c,0):nullptr;const gchar*n=z?gst_structure_get_name(z):nullptr;if(g_strcmp0(n,"video/x-h264")){bool h265=!g_strcmp0(n,"video/x-h265");if(c)gst_caps_unref(c);if(h265)fail(e,"H.265 unsupported; Stage 5B requires H.264");return;}if(c)gst_caps_unref(c);if(s->h264_linked)return;GstPad*q=gst_element_get_static_pad(s->parser,"sink");if(!q||gst_pad_link(p,q)!=GST_PAD_LINK_OK)fail(e,"Could not link HLS H.264");else{s->h264_linked=true;std::cout<<"Source "<<s->id<<": HLS H.264 video linked.\n";}if(q)gst_object_unref(q);}
GstPadProbeReturn meta(GstPad*,GstPadProbeInfo*i,gpointer d){if(!(i->type&GST_PAD_PROBE_TYPE_BUFFER))return GST_PAD_PROBE_OK;App*a=(App*)d;NvDsBatchMeta*b=gst_buffer_get_nvds_batch_meta(GST_PAD_PROBE_INFO_BUFFER(i));if(!b)return GST_PAD_PROBE_OK;for(NvDsMetaList*f=b->frame_meta_list;f;f=f->next){NvDsFrameMeta*m=(NvDsFrameMeta*)f->data;if(!m)continue;for(NvDsMetaList*x=m->obj_meta_list;x;x=x->next){NvDsObjectMeta*o=(NvDsObjectMeta*)x->data;if(o){std::ostringstream t;t<<"cam:"<<m->source_id<<' '<<label(o,a->labels)<<' '<<std::fixed<<std::setprecision(2)<<o->confidence<<" ID:"<<o->object_id;g_free(o->text_params.display_text);o->text_params.display_text=g_strdup(t.str().c_str());}}if(m->source_id<N&&m->num_obj_meta&&a->logged[m->source_id]<LIMIT){std::cout<<"frame="<<m->frame_num<<" source_id="<<m->source_id<<" objects="<<m->num_obj_meta<<'\n';for(NvDsMetaList*x=m->obj_meta_list;x;x=x->next){NvDsObjectMeta*o=(NvDsObjectMeta*)x->data;if(o)std::cout<<"  object_id="<<o->object_id<<" class_id="<<o->class_id<<" label="<<label(o,a->labels)<<" confidence="<<o->confidence<<'\n';}++a->logged[m->source_id];}}return GST_PAD_PROBE_OK;}
bool mux(GstElement*d,GstElement*m,guint n,App*a){GstPad*x=gst_element_get_static_pad(d,"src");std::string s="sink_"+std::to_string(n);GstPad*y=gst_element_request_pad_simple(m,s.c_str());if(!x||!y)return false;bool ok=gst_pad_link(x,y)==GST_PAD_LINK_OK;gst_object_unref(x);if(!ok){gst_element_release_request_pad(m,y);gst_object_unref(y);return false;}a->pads[n]=y;return true;} void release(GstElement*m,App*a){for(guint i=0;i<N;i++)if(a->pads[i]){gst_element_release_request_pad(m,a->pads[i]);gst_object_unref(a->pads[i]);}}
}
int main(int c,char**v){bool no_display=false;if(c==11&&std::string(v[1])=="--no-display"){no_display=true;++v;--c;}if(c!=10){std::cerr<<"Usage: "<<v[0]<<" [--no-display] <hls-0> <hls-1> <hls-2> <hls-3> <hls-4> <config> <labels> <tracker-lib> <tracker-config>\n";return 2;}gst_init(&c,&v);App a;a.labels=labels(v[7]);a.mux.name="Mux output";a.infer.name="Infer output";a.tracker.name="Tracker output";a.tiler.name="Tiler output";a.display.name="Display input";if(a.labels.empty())return 1;Src s[N];GstElement *p=gst_pipeline_new("stage5b"),*muxer=gst_element_factory_make("nvstreammux","mux"),*inf=gst_element_factory_make("nvinfer","infer"),*tr=gst_element_factory_make("nvtracker","tracker"),*til=gst_element_factory_make("nvmultistreamtiler","tiler"),*cv=gst_element_factory_make("nvvideoconvert","convert"),*cf=gst_element_factory_make("capsfilter","rgba"),*osd=gst_element_factory_make("nvdsosd","osd"),*sink=gst_element_factory_make(no_display?"fakesink":"nveglglessink","sink");GstElement*src[N],*hd[N],*td[N],*pa[N],*hc[N],*de[N],*identity[N];if(!p||!muxer||!inf||!tr||!til||!cv||!cf||!osd||!sink)return 1;if(no_display)std::cout<<"Display sink: fakesink (--no-display)\n";else g_object_set(sink,"sync",FALSE,nullptr);g_object_set(muxer,"live-source",TRUE,"batch-size",5,"width",1280,"height",720,"batched-push-timeout",4000000,nullptr);g_object_set(inf,"config-file-path",v[6],nullptr);g_object_set(tr,"tracker-width",960,"tracker-height",544,"gpu-id",0,"ll-lib-file",v[8],"ll-config-file",v[9],nullptr);g_object_set(til,"rows",2,"columns",3,"width",1920,"height",720,nullptr);GstCaps*rc=gst_caps_from_string("video/x-raw(memory:NVMM),format=RGBA");g_object_set(cf,"caps",rc,nullptr);gst_caps_unref(rc);gst_bin_add_many(GST_BIN(p),muxer,inf,tr,til,cv,cf,osd,sink,nullptr);for(guint i=0;i<N;i++){s[i].id=i;src[i]=gst_element_factory_make("souphttpsrc",nullptr);hd[i]=gst_element_factory_make("hlsdemux",nullptr);td[i]=gst_element_factory_make("tsdemux",nullptr);pa[i]=gst_element_factory_make("h264parse",nullptr);hc[i]=gst_element_factory_make("capsfilter",nullptr);de[i]=gst_element_factory_make("nvv4l2decoder",nullptr);identity[i]=gst_element_factory_make("identity",nullptr);if(!src[i]||!hd[i]||!td[i]||!pa[i]||!hc[i]||!de[i]||!identity[i])return 1;g_object_set(identity[i],"sync",TRUE,nullptr);GstStructure*h=gst_structure_new_empty("headers");gst_structure_set(h,"Referer",G_TYPE_STRING,"https://video.interra.ru/",nullptr);g_object_set(src[i],"location",v[i+1],"user-agent","Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36","extra-headers",h,nullptr);gst_structure_free(h);s[i].ts=td[i];s[i].parser=pa[i];GstCaps*q=gst_caps_from_string("video/x-h264,stream-format=byte-stream,alignment=au");g_object_set(hc[i],"caps",q,nullptr);gst_caps_unref(q);g_signal_connect(hd[i],"pad-added",G_CALLBACK(hls),&s[i]);g_signal_connect(td[i],"pad-added",G_CALLBACK(ts),&s[i]);gst_bin_add_many(GST_BIN(p),src[i],hd[i],td[i],pa[i],hc[i],de[i],identity[i],nullptr);if(!gst_element_link(src[i],hd[i])||!gst_element_link_many(pa[i],hc[i],de[i],identity[i],nullptr)||!mux(identity[i],muxer,i,&a))return 1;GstPad*z=gst_element_get_static_pad(de[i],"src");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,decode,&s[i],nullptr);gst_object_unref(z);}if(!gst_element_link_many(muxer,inf,tr,til,cv,cf,osd,sink,nullptr))return 1;GstPad*z=gst_element_get_static_pad(muxer,"src");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,count,&a.mux,nullptr);gst_object_unref(z);z=gst_element_get_static_pad(inf,"src");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,count,&a.infer,nullptr);gst_object_unref(z);z=gst_element_get_static_pad(tr,"src");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,count,&a.tracker,nullptr);gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,meta,&a,nullptr);gst_object_unref(z);z=gst_element_get_static_pad(til,"src");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,count,&a.tiler,nullptr);gst_object_unref(z);z=gst_element_get_static_pad(sink,"sink");gst_pad_add_probe(z,GST_PAD_PROBE_TYPE_BUFFER,count,&a.display,nullptr);gst_object_unref(z);std::signal(SIGINT,sig);std::cout<<"Display: tiler rows=2 columns=3.\n";if(gst_element_set_state(p,GST_STATE_PLAYING)==GST_STATE_CHANGE_FAILURE)return 1;GstBus*b=gst_element_get_bus(p);int code=0;while(!stop){GstMessage*x=gst_bus_timed_pop_filtered(b,100*GST_MSECOND,(GstMessageType)(GST_MESSAGE_ERROR|GST_MESSAGE_EOS));if(!x)continue;if(GST_MESSAGE_TYPE(x)==GST_MESSAGE_ERROR){GError*e=nullptr;gchar*d=nullptr;gst_message_parse_error(x,&e,&d);std::cerr<<"ERROR from "<<GST_OBJECT_NAME(GST_MESSAGE_SRC(x))<<": "<<redact(e->message,v)<<'\n';g_clear_error(&e);g_free(d);code=1;}gst_message_unref(x);break;}gst_object_unref(b);gst_element_set_state(p,GST_STATE_NULL);gst_element_get_state(p,nullptr,nullptr,GST_CLOCK_TIME_NONE);release(muxer,&a);for(guint i=0;i<N;i++)std::cout<<"Decoder source "<<i<<": "<<s[i].buffers<<'\n';std::cout<<a.mux.name<<": "<<a.mux.buffers<<'\n'<<a.infer.name<<": "<<a.infer.buffers<<'\n'<<a.tracker.name<<": "<<a.tracker.buffers<<'\n'<<a.tiler.name<<": "<<a.tiler.buffers<<'\n'<<a.display.name<<": "<<a.display.buffers<<'\n';gst_object_unref(p);return code;}